<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
const root=ref<HTMLElement>();let observer:MutationObserver|undefined
function primary(){const group=root.value?.querySelector('.entry-thumbnails,.inline-media');if(!group)return;const children=Array.from(group.children) as HTMLElement[];const first=children.find(el=>(el.matches('img')||el.querySelector('img'))&&!el.querySelector('.image-unavailable'))||children.find(el=>!el.matches('.image-unavailable')&&!el.querySelector('.image-unavailable'));for(const el of children){const active=el===first;if(el.classList.contains('entry-media-primary')!==active)el.classList.toggle('entry-media-primary',active)}}
onMounted(async()=>{await nextTick();primary();observer=new MutationObserver(primary);if(root.value)observer.observe(root.value,{subtree:true,childList:true,attributes:true,attributeFilter:['class','src']})})
onBeforeUnmount(()=>observer?.disconnect())
withDefaults(defineProps<{ids:string[];layout?:'cover'|'square'|'poster'|'photos'}>(),{layout:'photos'})
</script>
<template><div v-if="ids.length&&$slots.default" ref="root" class="entry-visuals" :class="'media-'+layout"><slot :ids="ids"/><span v-if="ids.length>1" class="entry-photo-count">{{ids.length}} 张关联照片</span></div></template>
<style scoped>
.entry-visuals{min-width:0}.entry-visuals :deep(.entry-thumbnails),.entry-visuals :deep(.inline-media){display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:0;min-width:0}.entry-visuals :deep(figure),.entry-visuals :deep(.inline-media){margin:0!important;width:100%!important;min-width:0}.entry-visuals :deep(.body-photo-button){aspect-ratio:inherit;background:transparent!important}.entry-visuals :deep(img){display:block;width:100%;max-width:100%;aspect-ratio:4/3;height:auto!important;object-fit:cover!important;border-radius:8px}.entry-visuals :deep(.private-image-status){font-size:11px;overflow-wrap:anywhere;max-width:100%;border:1px solid var(--ui-line);border-radius:8px}.media-cover :deep(.entry-thumbnails)>.entry-media-primary,.media-cover :deep(.inline-media)>.entry-media-primary{grid-column:1/-1}.media-cover :deep(.entry-thumbnails)>.entry-media-primary,.media-cover :deep(.inline-media)>.entry-media-primary img{aspect-ratio:16/9;max-height:280px;object-fit:cover}.media-square :deep(img){aspect-ratio:1}.media-poster :deep(img){aspect-ratio:2/3}.media-square :deep(.entry-thumbnails)>.entry-media-primary,.media-poster :deep(.entry-thumbnails)>.entry-media-primary,.media-square :deep(.inline-media)>.entry-media-primary,.media-poster :deep(.inline-media)>.entry-media-primary{grid-column:1/-1}.entry-photo-count{display:block;font-size:11px;color:var(--ui-muted);margin-top:6px}.media-photos{margin-top:14px}
.media-square :deep(.entry-thumbnails),.media-poster :deep(.entry-thumbnails),.media-square :deep(.inline-media),.media-poster :deep(.inline-media){grid-template-columns:repeat(2,minmax(0,1fr))}
</style>
